```go
package main

import (
	"encoding/json"
	"fmt"
)

type Detail struct {
	Code int `json:"code"`
}
type Reply struct {
	Count  int      `json:"count,omitempty"`
	Labels []string `json:"labels,omitempty"`
	Detail Detail   `json:"detail,omitempty"`
}

func main() {
	b, err := json.Marshal(Reply{})
	if err != nil {
		panic(err)
	}
	fmt.Println(string(b))
}
```
Count and Labels disappear, while the zero-valued Detail struct remains as an object.

```go
package main

import (
	"encoding/json"
	"fmt"
)

type Point struct{ X, Y int }
type Sample struct {
	Old   Point `json:"old,omitempty"`
	New   Point `json:"new,omitzero"`
	Items []int `json:"items,omitzero"`
}

func main() {
	b, err := json.Marshal(Sample{Items: make([]int, 0)})
	if err != nil {
		panic(err)
	}
	fmt.Println(string(b))
}
```
The zero Old struct remains, the zero New struct disappears, and the non-nil empty Items slice remains.

```go
package main

import (
	"encoding/json"
	"fmt"
)

type Patch struct {
	Count *int `json:"count"`
}

func main() {
	for _, input := range []string{`{}`, `{"count":0}`, `{"count":3}`} {
		var patch Patch
		if err := json.Unmarshal([]byte(input), &patch); err != nil {
			panic(err)
		}
		if patch.Count == nil {
			fmt.Println("missing-or-null")
		} else {
			fmt.Println(*patch.Count)
		}
	}
}
```
The pointer preserves explicit zero, while this simple model intentionally treats missing and null alike.
